import { NextRequest, NextResponse } from 'next/server';

import {
  ensureApiKeyAuthorized,
  extractApiKeyUserId,
} from '@/lib/server/auth/apiKeyAuth';
import { executeTool } from '@/lib/server/chatgptToolExecutor';

const ALLOWED_CLIENT_TOOL_IDS = new Set([
  'query_org_memory',
  'recommend_next_action',
]);

export async function POST(request: NextRequest) {
  const unauthorized = await ensureApiKeyAuthorized(request);
  if (unauthorized) return unauthorized;

  const userId = await extractApiKeyUserId(request);
  if (!userId) {
    return NextResponse.json(
      { ok: false, error: 'API key authentication failed' },
      { status: 401 }
    );
  }

  const body = await request.json().catch(() => null);
  if (!body || typeof body !== 'object') {
    return NextResponse.json(
      { ok: false, error: 'Invalid JSON body' },
      { status: 400 }
    );
  }

  const rawToolId = typeof body.tool_id === 'string' ? body.tool_id.trim() : '';
  if (!rawToolId) {
    return NextResponse.json(
      { ok: false, error: 'tool_id is required' },
      { status: 400 }
    );
  }

  const normalizedToolId = rawToolId.startsWith('chatgpt.')
    ? rawToolId.slice('chatgpt.'.length)
    : rawToolId;

  if (!ALLOWED_CLIENT_TOOL_IDS.has(normalizedToolId)) {
    return NextResponse.json(
      {
        ok: false,
        error: `Tool ${normalizedToolId} is not available through the client API`,
      },
      { status: 403 }
    );
  }

  const args =
    body.args && typeof body.args === 'object'
      ? (body.args as Record<string, unknown>)
      : {};

  const result = await executeTool(`chatgpt.${normalizedToolId}`, args, {
    userId,
    projectId: typeof body.project_id === 'string' ? body.project_id : null,
    initiativeId:
      typeof body.initiative_id === 'string' ? body.initiative_id : null,
    runId: typeof body.run_id === 'string' ? body.run_id : null,
  });

  return NextResponse.json({
    ok: result.ok,
    data: result.ok ? result.data : undefined,
    error: result.ok ? undefined : result.error,
    tool_id: normalizedToolId,
    execution_time_ms: result.executionTimeMs,
  });
}

