import { z } from 'zod';

import { errors } from '@/lib/server/apiErrors';

export const CLIENT_ARTIFACT_CONTRACT_VERSION = '2026-02-18';
export const CLIENT_ARTIFACT_FALLBACK_TYPE = 'shared.project_handbook';

export const CLIENT_ARTIFACT_ENTITY_TYPES = [
  'project',
  'initiative',
  'workstream',
  'milestone',
  'task',
  'decision',
] as const;

export type ClientArtifactEntityType =
  (typeof CLIENT_ARTIFACT_ENTITY_TYPES)[number];

export const WORK_ARTIFACT_STORAGE_ENTITY_TYPES = [
  'project',
  'initiative',
  'milestone',
  'task',
  'decision',
] as const;

export type WorkArtifactStorageEntityType =
  (typeof WORK_ARTIFACT_STORAGE_ENTITY_TYPES)[number];

const WORK_ARTIFACT_STATUS_VALUES = [
  'draft',
  'in_review',
  'approved',
  'changes_requested',
  'superseded',
  'archived',
] as const;

const CREATE_SCHEMA = z
  .object({
    id: z.string().uuid().optional(),
    artifact_id: z.string().uuid().optional(),
    entity_type: z.enum(CLIENT_ARTIFACT_ENTITY_TYPES),
    entity_id: z.string().uuid(),
    initiative_id: z.string().uuid().optional(),
    name: z.string().trim().min(1).max(500),
    artifact_type: z.string().trim().min(1).max(120),
    description: z.string().trim().max(4_000).nullable().optional(),
    artifact_url: z.string().trim().min(1).max(2_000).optional(),
    external_url: z.string().trim().max(2_000).optional(),
    preview_markdown: z.string().max(25_000).optional(),
    status: z.enum(WORK_ARTIFACT_STATUS_VALUES).optional(),
    metadata: z.record(z.string(), z.unknown()).optional(),
    created_by_type: z.enum(['human', 'agent']).optional(),
    created_by_id: z.string().uuid().optional(),
  })
  .strict()
  .superRefine((value, ctx) => {
    if (value.id && value.artifact_id && value.id !== value.artifact_id) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: 'id and artifact_id must match when both are provided',
        path: ['artifact_id'],
      });
    }
    if (!value.artifact_url && !value.external_url) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: 'artifact_url or external_url is required',
        path: ['artifact_url'],
      });
    }
  });

const LIST_SCHEMA = z
  .object({
    entity_type: z.enum(CLIENT_ARTIFACT_ENTITY_TYPES),
    entity_id: z.string().uuid(),
    kind: z.string().trim().min(1).max(120).optional(),
    limit: z.number().int().min(1).max(50).default(10),
  })
  .strict();

function zodIssuesToMessage(result: { success: boolean; error?: z.ZodError }) {
  if (result.success) return null;
  return result.error?.issues.map((issue: { message: string }) => issue.message).join('; ') ?? 'Validation failed';
}

export type ClientArtifactCreateInput = Omit<
  z.infer<typeof CREATE_SCHEMA>,
  'id'
> & {
  artifact_id?: string;
};

export function parseClientArtifactCreateBody(
  body: unknown
): ClientArtifactCreateInput {
  const result = CREATE_SCHEMA.safeParse(body);
  if (!result.success) {
    throw errors.badRequest(
      `Invalid artifact create payload: ${zodIssuesToMessage(result)}`
    );
  }

  const parsed = result.data;
  return {
    ...parsed,
    artifact_id: parsed.artifact_id ?? parsed.id,
  };
}

export type ClientArtifactListQuery = z.infer<typeof LIST_SCHEMA>;

export function parseClientArtifactListQuery(
  searchParams: URLSearchParams
): ClientArtifactListQuery {
  const limitRaw = searchParams.get('limit');
  const limit = limitRaw
    ? Number.isFinite(Number(limitRaw))
      ? Number(limitRaw)
      : NaN
    : undefined;

  const candidate = {
    entity_type: searchParams.get('entity_type') ?? undefined,
    entity_id: searchParams.get('entity_id') ?? undefined,
    kind: searchParams.get('kind') ?? undefined,
    limit,
  };

  const result = LIST_SCHEMA.safeParse(candidate);
  if (!result.success) {
    throw errors.badRequest(
      `Invalid artifact query params: ${zodIssuesToMessage(result)}`
    );
  }
  return result.data;
}

