export function withAuth(
  options: { optional?: boolean; allowServiceAuth?: boolean } = {}
) {
  const { optional = false, allowServiceAuth = false } = options;
  return (handler: ApiHandler): ApiHandler => {
    return async (req: Request, ctx: ApiContext) => {
      const resolved = await resolveApiUser();
      let nextCtx: ApiContext = { ...ctx, ...resolved };
      if (allowServiceAuth && !nextCtx.userId) {
        try {
          const unauthorized = ensureServiceRequestAuthorized(req);
          if (!unauthorized) {
            const gatewayActor = verifyGatewayActor(req);
            if (gatewayActor) {
              nextCtx = {
                ...nextCtx,
                userId: gatewayActor.userId,
                externalUserId: gatewayActor.userId,
                email: gatewayActor.email,
              };
            }
          }
        } catch {
          // Runtime has no service key configured; keep normal user auth behavior.
        }
      }
      if (!optional && !nextCtx.userId) {
        return jsonError(
          ApiErrorCode.AUTHENTICATION_ERROR,
          'Authentication required'
        );
      }
      return handler(req, nextCtx);
    };
  };
}

export function withCsrf() {
  return (handler: ApiHandler): ApiHandler => {
    return async (req: Request, ctx: ApiContext) => {
      if (!(await verifyCsrf(req))) {
        return jsonError(
          ApiErrorCode.AUTHORIZATION_ERROR,
          'Invalid CSRF token'
        );
      }
      return handler(req, ctx);
    };
  };
}

export function withRateLimit(options: {
  limit: number;
  windowMs: number;
  key?: (req: Request, ctx: ApiContext) => string;
  deadlineMs?: number;
  failOpenOnTimeout?: boolean;
}) {
  return (handler: ApiHandler): ApiHandler => {
    return async (req: Request, ctx: ApiContext) => {
      const ip =
        (req.headers.get('x-forwarded-for') || '').split(',')[0] || null;
      const defaultKey = `${
        new URL(req.url).pathname
      }:${req.method.toLowerCase()}`;
      const key = rateLimitKey(
        ip,
        options.key ? options.key(req, ctx) : defaultKey
      );
      let timedOut = false;
      let allowed = true;
      let resetAt = Date.now() + options.windowMs;

    if (idempotency_key) {
      const { data: existing, error: existingError } = await admin
        .from('execution_receipts')
        .select('id')
        .eq('workspace_id', workspace_id)
        .contains('context_used', { idempotency_key })
        .maybeSingle();
      if (existingError) {
        logger.warn('[flywheel/receipts] Idempotency lookup failed', {
          error: existingError.message,
        });
      } else if (existing?.id) {
        return NextResponse.json({
          ok: true,
          receipt_id: existing.id,
          idempotent: true,
        });
      }
    }

    const now = new Date().toISOString();
    const agentType =
      asString(evidence.agent_type) ??
      asString(evidence.source_client) ??
      asString(evidence.source) ??
      'mcp';
    const qualityScore = normalizeQualityScore(evidence.quality_score);

    const { data: receipt, error } = await admin
      .from('execution_receipts')
      .insert({
        workspace_id,
        receipt_type: executionReceiptType,
        intent: receipt_type,
        summary,
        ref_type: refType,
        ref_id: refId,
        entity_refs: {
          entity_type: entity_type ?? null,
          entity_id: entity_id ?? null,
          artifact_id: artifact_id ?? null,
        },
        agent_type: agentType,
        context_used: {
          source: 'mcp',
          evidence,
          idempotency_key: idempotency_key ?? null,
        },
        quality_score: qualityScore,
        status: 'completed',
        started_at: now,
        completed_at: now,
      })
      .select('id')
      .single();

    if (error) {
      logger.error('[flywheel/receipts] Insert failed', {
        error: error.message,
      });
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({
      ok: true,
      receipt_id: receipt.id,
      receipt_type: executionReceiptType,
      requested_receipt_type: receipt_type,
      ref_type: refType,
      ref_id: refId,
    });
  })
);
